using System.Runtime.InteropServices;

// .NET 9 breaking change: Environment.GetEnvironmentVariable returns null for
// empty env vars on Linux, making it impossible to distinguish "unset" from
// "explicitly empty". Use native getenv which returns IntPtr.Zero only when unset.
partial class EnvVarCheck
{
    [LibraryImport("libc", EntryPoint = "getenv", StringMarshalling = StringMarshalling.Utf8)]
    private static partial IntPtr NativeGetEnv(string name);

    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        IntPtr ptr = NativeGetEnv("MY_FLAG");
        if (ptr == IntPtr.Zero)
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
    }
}

